module top_module(
    input clk,
    input reset,           // Synchronous reset
    input [7:0] d,
    output [7:0] q,
    output reg[7:0] final_output
);// Define the 8-bit D flip-flop with active high synchronous reset
    reg [7:0] shift_reg;
    always @(negedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else begin
            shift_reg <= {shift_reg[6:0], d};
        end
    end
    assign q = shift_reg[7];

    // Define the 64-bit Johnson counter generated by an LFSR
    reg [63:0] lfsr_reg = 64'h1;
    always @(posedge clk) begin
        lfsr_reg <= {lfsr_reg[62:0], lfsr_reg[0] ^ lfsr_reg[63]};
    end

    // Define the functional module that performs XOR operation on the two inputs
    always @(posedge clk) begin
        final_output <= q ^ lfsr_reg[7:0];
    end

endmodule